ci = repo.search("(?i)fixme")
files = {}
for h in ci:
    files[h.path] = files.get(h.path, 0) + 1

contents = {}
for p in ["src/a.py", "src/sub/b.py"]:
    contents[p] = repo.read(p, missing_ok=True)

listing = repo.list("src")
sublisting = repo.list("src/sub")

return {
  "case_insensitive_hits": [{"path": h.path, "line": h.line, "text": h.text.strip()} for h in ci],
  "files": files,
  "a.py": contents.get("src/a.py"),
  "b.py": contents.get("src/sub/b.py"),
  "src_listing": listing,
  "sub_listing": sublisting,
}
